window.PAIRS=[{"n":2,"s":0.419,"o":{"i":"산업안2022_12-18-5","t":"규정을 작성해야 하는 사업의 사업주는 규정을 작성해야 할 사유가 발생한 날부터 30일 이내에 작성해야 한다.","y":2022,"e":"산업안전지도사 1차"},"x":{"i":"산업안2021_11-05-1","t":"사업주는 안전보건관리규정을 작성해야 할 사유가 발생한 날부터 30일 이내에, 이를 변경할 사유가 발생한 경우에는 15일 이내에 안전보건관리규정을 작성해야 한다.","y":2021,"e":"산업안전지도사 1차"}},{"n":2,"s":0.41,"o":{"i":"산업안2021_11-01-1","t":"안전보건관리책임자는 안전관리자와 보건관리자를 지휘ㆍ감독한다.","y":2021,"e":"산업안전지도사 1차"},"x":{"i":"산업안2025_15-04-4","t":"안전관리자와 보건관리자는 안전보건관리책임자의 지휘·감독을 받지 아니한다.","y":2025,"e":"산업안전지도사 1차"}},{"n":2,"s":0.345,"o":{"i":"산업안2024_14-06-3","t":"상시 근로자 수가 100명인 1차 금속 제조업의 사업장에는 안전보건관리책임자를 두어야 한다.","y":2024,"e":"산업안전지도사 1차"},"x":{"i":"산업안2024_14-06-4","t":"건설업의 경우 공사금액이 10억원인 사업장에는 안전보건관리책임자를 두어야 한다.","y":2024,"e":"산업안전지도사 1차"}},{"n":1,"s":0.762,"o":{"i":"산업안2026_16-04-3","t":"“안전보건진단”이란 산업재해를 예방하기 위하여 잠재적 위험성을 발견하고 그 개선대책을 수립할 목적으로 조사ㆍ평가하는 것을 말한다.","y":2026,"e":"산업안전지도사 1차"},"x":{"i":"산업안2024_14-10-5","t":"\"위험성평가\"란 산업재해를 예방하기 위하여 잠재적 위험성을 발견하고 그 개선대책을 수립할 목적으로 조사ㆍ평가하는 것을 말한다.","y":2024,"e":"산업안전지도사 1차"}},{"n":1,"s":0.65,"o":{"i":"산업안2021_11-02-5","t":"고용노동부장관은 산업재해 예방을 위하여 중앙행정기관의 장과 지방자치단체의 장 또는 공단 등 관련 기관ㆍ단체의 장에게「고용보험법」에 따른 근로자의 피보 험자격의 취득 및 상실 등에 관한 정보의 제공을 요청할 수 있다.","y":2021,"e":"산업안전지도사 1차"},"x":{"i":"산업안2021_11-02-4","t":"고용노동부장관은 산업재해 예방을 위하여 중앙행정기관의 장과 지방자치단체의 장 또는 공단 등 관련 기관ㆍ단체의 장에게「소득세법」에 따른 납세실적에 관한 정보의 제공을 요청할 수 있다.","y":2021,"e":"산업안전지도사 1차"}},{"n":1,"s":0.557,"o":{"i":"산업안2025_15-01-3","t":"\"관계수급인\"이란 도급이 여러 단계에 걸쳐 체결된 경우에 각 단계별로 도급받은 사업주 전부를 말한다.","y":2025,"e":"산업안전지도사 1차"},"x":{"i":"산업안2026_16-04-4","t":"“관계수급인”이란 도급이 여러 단계에 걸쳐 체결된 경우에 각 단계별로 도급받은 사업주 중 고용노동부령으로 정하는 자를 말한다.","y":2026,"e":"산업안전지도사 1차"}},{"n":1,"s":0.524,"o":{"i":"산업안2021_11-07-1","t":"건설공사발주자는 도급인에 해당한다.","y":2021,"e":"산업안전지도사 1차"},"x":{"i":"산업안2025_15-01-5","t":"건설공사발주자는 \"도급인\"에 해당한다.","y":2025,"e":"산업안전지도사 1차"}},{"n":9,"s":0.552,"o":{"i":"산업안2022_12-08-3","t":"크레인, 리프트, 곤돌라는 설치ㆍ이전하는 경우뿐만 아니라 주요 구조 부분을 변경하는 경우에도 안전인증을 받아야 한다.","y":2022,"e":"산업안전지도사 1차"},"x":{"i":"산업안2025_15-16-4","t":"곤돌라는 설치·이전하는 경우뿐만 아니라 주요 구조 부분을 변경하는 경우에도 안전인증을 받지 않아도 된다.","y":2025,"e":"산업안전지도사 1차"}},{"n":9,"s":0.536,"o":{"i":"산업안2025_15-16-3","t":"안전인증이 취소된 자는 안전인증이 취소된 날부터 1년 이내에는 취소된 유해·위험기계등에 대하여 안전인증을 신청할 수 없다.","y":2025,"e":"산업안전지도사 1차"},"x":{"i":"산업안2022_12-08-2","t":"거짓이나 그 밖의 부정한 방법으로 안전인증을 받은 사유로 안전인증이 취소 된 자는 안전인증이 취소된 날부터 3년 이내에는 취소된 유해ㆍ위험기계등에 대하여 안전인증을 신청할 수 없다.","y":2022,"e":"산업안전지도사 1차"}},{"n":7,"s":0.424,"o":{"i":"산업안2022_12-01-3","t":"관계수급인의 공사금액을 포함한 해당 공사의 총공사금액이 20억원 이상인 건설업의 경우 도급인은 그 사업장의 안전보건관리책임자를 안전보건총괄책임자로 지정하여야 한다.","y":2022,"e":"산업안전지도사 1차"},"x":{"i":"산업안2023_13-06-5","t":"관계수급인의 공사금액을 포함한 해당 공사의 총공사금액이 10억원 이상인 건설업은 안전보건총괄책임자 지정 대상사업에 해당한다.","y":2023,"e":"산업안전지도사 1차"}},{"n":7,"s":0.382,"o":{"i":"산업안2023_13-06-3","t":"안전 및 보건에 관한 협의체는 도급인 및 그의 수급인 전원으로 구성해야 한다.","y":2023,"e":"산업안전지도사 1차"},"x":{"i":"산업안2025_15-07-1","t":"도급인 및 그의 수급인 대표로 구성해야 한다.","y":2025,"e":"산업안전지도사 1차"}},{"n":7,"s":0.364,"o":{"i":"산업안2022_12-01-5","t":"도급인은 제조업 작업장의 순회점검을 2일에 1회 이상 실시하여야 한다.","y":2022,"e":"산업안전지도사 1차"},"x":{"i":"산업안2023_13-06-2","t":"토사석 광업의 도급인은 3일에 1회 이상 작업장 순회점검을 실시하여야 한다.","y":2023,"e":"산업안전지도사 1차"}},{"n":12,"s":0.512,"o":{"i":"산업안2023_13-19-2","t":"사업주는 근로자대표가 요구하면 작업환경측정 시 근로자대표를 참석시켜야 한다.","y":2023,"e":"산업안전지도사 1차"},"x":{"i":"산업안2026_16-19-5","t":"사업주는 근로자대표가 요구하더라도 작업환경측정 시 근로자대표를 참석시키지 않아도 된다.","y":2026,"e":"산업안전지도사 1차"}},{"n":14,"s":0.304,"o":{"i":"산업안2021_11-24-2","t":"산업안전지도사는 유해·위험의 방지대책에 관한 평가·지도의 직무를 수행한다.","y":2021,"e":"산업안전지도사 1차"},"x":{"i":"산업안2021_11-24-1","t":"산업안전지도사는 산업보건에 관한 조사ㆍ연구의 직무를 수행한다.","y":2021,"e":"산업안전지도사 1차"}}];
